package org.humanjourney.core.geography.map;
import org.humanjourney.core.mapfeature.FeatureGeometry;
import org.humanjourney.core.geography.GeographyGeometry;
import java.util.*;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import org.humanjourney.core.geography.DiscoveryLedger;
import org.humanjourney.core.water.WaterGeography.Point;
/** Geography-map protocol2: small areas batch normally; a large feature is bounded serialized fragments. */
public final class MapPackets {
 public static final int AREAS_PER_PACKET=8,REMOVALS_PER_PACKET=64,MAX_BYTES=48*1024,MAX_PARTS=8192,MAX_AREAS=4608,CHUNK_BYTES=16*1024,MAX_AREA_BYTES=288*1024,MAX_TRANSFER_BYTES=24*1024*1024;
 public enum Mode{FULL,DELTA,CLEAR}public enum Request{INSTANCE}
 public record Header(UUID session,long sequence,long discovery,long data,long presentation){public Header{if(session==null||sequence<=0||discovery<0||data<0||presentation<0)throw new IllegalArgumentException("invalid geography revision");}}
 public record Fragment(MapArea.Key key,int index,int count,int length,byte[] data){public Fragment{data=data.clone();if(key==null||key.kind()==null||!DiscoveryLedger.validId(key.id())||length<1||length>MAX_AREA_BYTES||count!=(length+CHUNK_BYTES-1)/CHUNK_BYTES||index<0||index>=count||data.length!=Math.min(CHUNK_BYTES,length-index*CHUNK_BYTES))throw new IllegalArgumentException("invalid geography fragment");}@Override public byte[] data(){return data.clone();}@Override public boolean equals(Object o){return o instanceof Fragment f&&key.equals(f.key)&&index==f.index&&count==f.count&&length==f.length&&Arrays.equals(data,f.data);}@Override public int hashCode(){return Objects.hash(key,index,count,length,Arrays.hashCode(data));}}
 public record Frame(Header header,Mode mode,long base,int part,int parts,List<MapArea> areas,List<MapArea.Key> removals,String error,List<Fragment> fragments){
  public Frame(Header h,Mode m,long b,int p,int n,List<MapArea> f,List<MapArea.Key> r,String e){this(h,m,b,p,n,f,r,e,List.of());}
  public Frame{areas=List.copyOf(areas);removals=List.copyOf(removals);fragments=List.copyOf(fragments);if(error==null){Objects.requireNonNull(header);Objects.requireNonNull(mode);if(parts<1||parts>MAX_PARTS||part<0||part>=parts||areas.size()>AREAS_PER_PACKET||removals.size()>REMOVALS_PER_PACKET||fragments.size()>1||!fragments.isEmpty()&&(!areas.isEmpty()||!removals.isEmpty())||base<0||mode==Mode.DELTA&&(base==0||base>=header.sequence())||mode!=Mode.DELTA&&base!=0||mode==Mode.FULL&&!removals.isEmpty()||mode==Mode.CLEAR&&(parts!=1||!areas.isEmpty()||!removals.isEmpty()||!fragments.isEmpty()))throw new IllegalArgumentException("invalid geography transfer bounds");for(var f:areas)if(f.shape().vertexCount()>256)throw new IllegalArgumentException("large area requires fragments");for(var key:removals)if(key==null||key.kind()==null||!DiscoveryLedger.validId(key.id()))throw new IllegalArgumentException("invalid removed map key");}}
  public static Frame bad(String error){return new Frame(null,Mode.FULL,0,0,1,List.of(),List.of(),error);}public boolean valid(){return error==null;}
 }
 private static int count(FriendlyByteBuf b,int max){int n=b.readVarInt();if(n<0||n>max)throw new IllegalArgumentException("geography count outside bounds");return n;}
 private static void points(FriendlyByteBuf b,List<Point> points){b.writeVarInt(points.size());for(var p:points){b.writeDouble(p.x());b.writeDouble(p.z());}}
 private static final class ReadBudget{int vertices,rings;}
 private static List<Point> points(FriendlyByteBuf b,ReadBudget budget){int n=count(b,GeographyGeometry.MAX_VERTICES);budget.vertices+=n;if(budget.vertices>GeographyGeometry.MAX_VERTICES)throw new IllegalArgumentException("geography vertex budget exceeded");var out=new ArrayList<Point>();for(int i=0;i<n;i++)out.add(new Point(b.readDouble(),b.readDouble()));return out;}
 private static FeatureGeometry.Ring ring(FriendlyByteBuf b,ReadBudget budget){if(++budget.rings>GeographyGeometry.MAX_RINGS)throw new IllegalArgumentException("geography ring budget exceeded");return new FeatureGeometry.Ring(points(b,budget));}
 private static void part(FriendlyByteBuf b,FeatureGeometry.Part p){points(b,p.outer().points());b.writeVarInt(p.holes().size());for(var h:p.holes())points(b,h.points());}
 private static FeatureGeometry.Part part(FriendlyByteBuf b,ReadBudget budget){var outer=ring(b,budget);int holes=count(b,GeographyGeometry.MAX_RINGS-1);var list=new ArrayList<FeatureGeometry.Ring>();for(int i=0;i<holes;i++)list.add(ring(b,budget));return new FeatureGeometry.Part(outer,list);}
 private static void key(FriendlyByteBuf b,MapArea.Key key){b.writeVarInt(key.kind().ordinal());b.writeUtf(key.id(),64);}
 private static MapArea.Key key(FriendlyByteBuf b){return new MapArea.Key(MapArea.Kind.values()[count(b,MapArea.Kind.values().length-1)],b.readUtf(64));}
 private static void view(FriendlyByteBuf b,MapArea v){key(b,v.key());b.writeUtf(v.label(),128);b.writeUtf(v.dimension(),256);b.writeVarInt(v.priority());b.writeUtf(v.parent(),64);b.writeVarInt(v.shape().kind().ordinal());b.writeVarInt(v.shape().parts().size());for(var p:v.shape().parts())part(b,p);}
 private static MapArea view(FriendlyByteBuf b){var key=key(b);String label=b.readUtf(128),dimension=b.readUtf(256);int priority=b.readVarInt();String parent=b.readUtf(64);int kind=count(b,FeatureGeometry.Kind.values().length-1);if(FeatureGeometry.Kind.values()[kind]==FeatureGeometry.Kind.POLYLINE)throw new IllegalArgumentException("geography is areal");var budget=new ReadBudget();int size=count(b,GeographyGeometry.MAX_RINGS);var parts=new ArrayList<FeatureGeometry.Part>();for(int i=0;i<size;i++)parts.add(part(b,budget));var geometry=FeatureGeometry.Kind.values()[kind]==FeatureGeometry.Kind.POLYGON?(parts.size()==1?FeatureGeometry.polygon(parts.getFirst()):failGeometry()):FeatureGeometry.multipolygon(parts);return new MapArea(key.kind(),key.id(),label,dimension,priority,parent,geometry,null);}
 private static FeatureGeometry failGeometry(){throw new IllegalArgumentException("invalid polygon part count");}
 private static byte[] serialize(MapArea v){var b=new FriendlyByteBuf(io.netty.buffer.Unpooled.buffer());try{view(b,v);if(b.readableBytes()>MAX_AREA_BYTES)throw new IllegalArgumentException("geography exceeds serialized byte limit");var bytes=new byte[b.readableBytes()];b.readBytes(bytes);return bytes;}finally{b.release();}}
 public static final StreamCodec<RegistryFriendlyByteBuf,Frame> CODEC=new StreamCodec<>(){
  public void encode(RegistryFriendlyByteBuf b,Frame f){if(!f.valid())throw new IllegalArgumentException("rejected geography frame");int start=b.writerIndex();var h=f.header();b.writeUUID(h.session());b.writeVarLong(h.sequence());b.writeVarLong(h.discovery());b.writeVarLong(h.data());b.writeVarLong(h.presentation());b.writeVarInt(f.mode().ordinal());b.writeVarLong(f.base());b.writeVarInt(f.part());b.writeVarInt(f.parts());b.writeVarInt(f.areas().size());for(var v:f.areas())view(b,v);b.writeVarInt(f.removals().size());for(var key:f.removals())key(b,key);b.writeVarInt(f.fragments().size());for(var c:f.fragments()){key(b,c.key());b.writeVarInt(c.index());b.writeVarInt(c.count());b.writeVarInt(c.length());b.writeByteArray(c.data());}if(b.writerIndex()-start>MAX_BYTES)throw new IllegalArgumentException("geography packet exceeds byte limit");}
  public Frame decode(RegistryFriendlyByteBuf b){try{if(b.readableBytes()>MAX_BYTES)throw new IllegalArgumentException("geography packet too large");var h=new Header(b.readUUID(),b.readVarLong(),b.readVarLong(),b.readVarLong(),b.readVarLong());int mode=count(b,Mode.values().length-1);long base=b.readVarLong();int part=b.readVarInt(),parts=b.readVarInt(),n=count(b,AREAS_PER_PACKET);var areas=new ArrayList<MapArea>();for(int i=0;i<n;i++)areas.add(view(b));var removed=new ArrayList<MapArea.Key>();n=count(b,REMOVALS_PER_PACKET);for(int i=0;i<n;i++)removed.add(key(b));var fragments=new ArrayList<Fragment>();n=count(b,1);for(int i=0;i<n;i++)fragments.add(new Fragment(key(b),b.readVarInt(),b.readVarInt(),b.readVarInt(),b.readByteArray(CHUNK_BYTES)));if(b.readableBytes()!=0)throw new IllegalArgumentException("unexpected geography bytes");return new Frame(h,Mode.values()[mode],base,part,parts,areas,removed,null,fragments);}catch(RuntimeException error){b.skipBytes(b.readableBytes());return Frame.bad("Malformed geography packet: "+error.getClass().getSimpleName());}}
 };
 public static final StreamCodec<RegistryFriendlyByteBuf,Request> REQUEST=StreamCodec.unit(Request.INSTANCE);
 public static List<MapArea> assemble(Collection<Fragment> fragments){var groups=new TreeMap<MapArea.Key,List<Fragment>>();long total=0;for(var c:fragments){total+=c.data.length;if(total>MAX_TRANSFER_BYTES)throw new IllegalArgumentException("fragment transaction too large");groups.computeIfAbsent(c.key(),id->new ArrayList<>()).add(c);}if(groups.size()>MAX_AREAS)throw new IllegalArgumentException("too many fragmented areas");var result=new ArrayList<MapArea>();long vertices=0,rings=0;for(var group:groups.entrySet()){var first=group.getValue().getFirst();var slots=new Fragment[first.count()];for(var c:group.getValue()){if(c.count()!=first.count()||c.length()!=first.length()||slots[c.index()]!=null)throw new IllegalArgumentException("inconsistent/duplicate feature fragment");slots[c.index()]=c;}var bytes=new byte[first.length()];for(int i=0;i<slots.length;i++){if(slots[i]==null)throw new IllegalArgumentException("incomplete feature fragments");System.arraycopy(slots[i].data,0,bytes,i*CHUNK_BYTES,slots[i].data.length);}var b=new FriendlyByteBuf(io.netty.buffer.Unpooled.wrappedBuffer(bytes));try{var v=view(b);if(b.readableBytes()!=0||!v.key().equals(group.getKey()))throw new IllegalArgumentException("fragment identity/trailing bytes mismatch");vertices+=v.shape().vertexCount();rings+=v.shape().ringCount();if(vertices>GeographyGeometry.CATALOG_VERTICES||rings>GeographyGeometry.CATALOG_RINGS)throw new IllegalArgumentException("assembled geometry exceeds catalog budget");result.add(v);}finally{b.release();}}return List.copyOf(result);}
 private record Draft(List<MapArea> areas,List<MapArea.Key> removals,List<Fragment> fragments){}
 public static List<Frame> frames(Header h,Mode mode,long base,Collection<MapArea> entries,Collection<MapArea.Key> removed){MapGeometryBudget.check(entries);if(removed.size()>MAX_AREAS)throw new IllegalArgumentException("too many removals");var whole=new ArrayList<MapArea>();var chunks=new ArrayList<Fragment>();long bytes=0;for(var v:entries){bytes+=v.shape().vertexCount()*16L+v.shape().ringCount()*8L;if(v.shape().vertexCount()<=256)whole.add(v);else{var raw=serialize(v);int count=(raw.length+CHUNK_BYTES-1)/CHUNK_BYTES;for(int i=0;i<count;i++)chunks.add(new Fragment(v.key(),i,count,raw.length,Arrays.copyOfRange(raw,i*CHUNK_BYTES,Math.min(raw.length,(i+1)*CHUNK_BYTES))));}}if(bytes>MAX_TRANSFER_BYTES)throw new IllegalArgumentException("geography transaction too large");whole.sort(Comparator.comparing(MapArea::key));chunks.sort(Comparator.comparing(Fragment::key).thenComparingInt(Fragment::index));var removals=new ArrayList<>(new TreeSet<>(removed));int groups=Math.max((whole.size()+AREAS_PER_PACKET-1)/AREAS_PER_PACKET,(removals.size()+REMOVALS_PER_PACKET-1)/REMOVALS_PER_PACKET);var drafts=new ArrayList<Draft>();for(int i=0;i<groups;i++){int a=Math.min(i*AREAS_PER_PACKET,whole.size()),k=Math.min(i*REMOVALS_PER_PACKET,removals.size());drafts.add(new Draft(whole.subList(a,Math.min(a+AREAS_PER_PACKET,whole.size())),removals.subList(k,Math.min(k+REMOVALS_PER_PACKET,removals.size())),List.of()));}for(var c:chunks)drafts.add(new Draft(List.of(),List.of(),List.of(c)));if(drafts.isEmpty())drafts.add(new Draft(List.of(),List.of(),List.of()));if(drafts.size()>MAX_PARTS)throw new IllegalArgumentException("too many feature transfer parts");var out=new ArrayList<Frame>();for(int i=0;i<drafts.size();i++){var d=drafts.get(i);out.add(new Frame(h,mode,base,i,drafts.size(),d.areas(),d.removals(),null,d.fragments()));}return List.copyOf(out);}
 private MapPackets(){}
}
